#define HP_SIZE (2 * 1024 * 1024) // Typical 2MB page size
#define SHARE_ID 5000

void* addr_hint = NULL;

// Allocate private huge page segment (key=0)
void* private_mem = alloc_hugepages(0, addr_hint, HP_SIZE);

// Allocate shared huge page segment (key > 0)
void* shared_mem = alloc_hugepages(SHARE_ID, addr_hint, HP_SIZE);

if (private_mem != MAP_FAILED)
    free_hugepages(private_mem);

if (shared_mem != MAP_FAILED)
    free_hugepages(shared_mem);
